+/** Picks "ko" or "en" from an Accept-Language value (q-values, region tags); null if neither is listed. */
+export function pickLanguage(header) {
+  if (typeof header !== "string") return null;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...attrs] = part.trim().split(";");
+    const base = tag.trim().toLowerCase().split("-")[0];
+    if (base !== "ko" && base !== "en") continue;
+    let q = 1;
+    for (const a of attrs) {
+      const m = /^\s*q\s*=\s*([\d.]+)\s*$/i.exec(a);
+      if (m) q = Number(m[1]);
+    }
+    if (q > bestQ) {
+      best = base;
+      bestQ = q;
+    }
+  }
+  return best;
+}
+
 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
